WITH filtered AS (SELECT * FROM service_requests), valid AS (SELECT * FROM filtered WHERE created_date IS NOT NULL AND closed_date >= created_date AND resolution_hours >= 0), ranked AS (SELECT resolution_hours,ROW_NUMBER() OVER (ORDER BY resolution_hours) rn,COUNT(*) OVER () n FROM valid), fences AS (SELECT SUM(CASE WHEN rn=FLOOR((n-1)*0.25)+1 THEN resolution_hours*(1-((n-1)*0.25-FLOOR((n-1)*0.25))) WHEN rn=FLOOR((n-1)*0.25)+2 THEN resolution_hours*((n-1)*0.25-FLOOR((n-1)*0.25)) END) q1,SUM(CASE WHEN rn=FLOOR((n-1)*0.75)+1 THEN resolution_hours*(1-((n-1)*0.75-FLOOR((n-1)*0.75))) WHEN rn=FLOOR((n-1)*0.75)+2 THEN resolution_hours*((n-1)*0.75-FLOOR((n-1)*0.75)) END) q3 FROM ranked) SELECT v.complaint_type,v.request_count,m.valid_n,m.median_hours FROM (SELECT complaint_type,COUNT(*) request_count FROM filtered GROUP BY complaint_type) v JOIN (SELECT complaint_type,COUNT(*) valid_n,AVG(resolution_hours) mean_hours,AVG(CASE WHEN rn IN (FLOOR((n+1)/2),FLOOR((n+2)/2)) THEN resolution_hours END) median_hours FROM (SELECT complaint_type,resolution_hours,ROW_NUMBER() OVER (PARTITION BY complaint_type ORDER BY resolution_hours) rn,COUNT(*) OVER (PARTITION BY complaint_type) n FROM valid) r GROUP BY complaint_type) m ON v.complaint_type <=> m.complaint_type WHERE v.request_count >= %s AND m.median_hours >= %s ORDER BY v.request_count DESC,m.median_hours DESC;